CREATE MASKING POLICY IF NOT EXISTS SEC.MP_COUNTERPARTY_ID AS (v STRING) RETURNS STRING -> v
  COMMENT = 'Counterparty IDs are commercially sensitive – masked outside Finance.';

ALTER MASKING POLICY SEC.MP_COUNTERPARTY_ID SET BODY ->
    CASE
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',REGULATORY_SENSITIVE_DATA,') AND NOT (IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('NERC_AUDITORS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')) THEN 'COUNTERPARTY-***'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_DATA_POLICY,') AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') = 'restricted' THEN 'COUNTERPARTY-***'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_FINANCIAL_DATA,') AND (COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'restricted' AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'confidential') THEN 'COUNTERPARTY-***'
    WHEN IS_ROLE_IN_SESSION('BILLING_ANALYSTS') OR IS_ROLE_IN_SESSION('FINANCE_ANALYSTS_JUNIOR') OR IS_ROLE_IN_SESSION('OPERATIONS_VIEWERS') THEN 'COUNTERPARTY-***'
    WHEN IS_ROLE_IN_SESSION('FINANCE_ANALYSTS_SENIOR') OR IS_ROLE_IN_SESSION('FINANCE_MANAGERS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS') THEN v
    ELSE 'COUNTERPARTY-***'
    END;

ALTER MASKING POLICY SEC.MP_COUNTERPARTY_ID SET COMMENT = 'Counterparty IDs are commercially sensitive – masked outside Finance.';
